class Solution:
    def longestCommonPrefix(self, words: List[str]) -> List[int]:
        n = len(words)
        if n == 1:
            return [0]
        def lcp(a, b):
            m = min(len(a), len(b)); i = 0
            while i < m and a[i] == b[i]: i += 1
            return i
        adj = [lcp(words[i], words[i+1]) for i in range(n-1)]
        pre = adj[:]
        for i in range(1, n-1): pre[i] = max(pre[i-1], adj[i])
        suf = adj[:]
        for i in range(n-3, -1, -1): suf[i] = max(suf[i+1], adj[i])
        ans = []
        for i in range(n):
            best = 0
            if i - 2 >= 0: best = max(best, pre[i-2])
            if i + 1 <= n - 2: best = max(best, suf[i+1])
            ans.append(best)
        return ans

