class Solution {
public:
    vector<int> longestCommonPrefix(vector<string>& words) {
        int n = words.size();
        if (n == 1) return {0};
        auto lcp = [](const string& a, const string& b) {
            int m = min(a.size(), b.size()), i = 0;
            while (i < m && a[i] == b[i]) i++;
            return i;
        };
        vector<int> adj(n - 1);
        for (int i = 0; i + 1 < n; i++) adj[i] = lcp(words[i], words[i+1]);
        vector<int> pre = adj, suf = adj;
        for (int i = 1; i < n - 1; i++) pre[i] = max(pre[i-1], adj[i]);
        for (int i = n - 3; i >= 0; i--) suf[i] = max(suf[i+1], adj[i]);
        vector<int> ans(n);
        for (int i = 0; i < n; i++) {
            int best = 0;
            if (i - 2 >= 0) best = max(best, pre[i-2]);
            if (i + 1 <= n - 2) best = max(best, suf[i+1]);
            ans[i] = best;
        }
        return ans;
    }
};

