class Solution {
    public int[] longestCommonPrefix(String[] words) {
        int n = words.length;
        if (n == 1) return new int[]{0};
        int[] adj = new int[n - 1];
        for (int i = 0; i + 1 < n; i++) {
            String a = words[i], b = words[i+1];
            int m = Math.min(a.length(), b.length()), j = 0;
            while (j < m && a.charAt(j) == b.charAt(j)) j++;
            adj[i] = j;
        }
        int[] pre = adj.clone(), suf = adj.clone();
        for (int i = 1; i < n - 1; i++) pre[i] = Math.max(pre[i-1], adj[i]);
        for (int i = n - 3; i >= 0; i--) suf[i] = Math.max(suf[i+1], adj[i]);
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            int best = 0;
            if (i - 2 >= 0) best = Math.max(best, pre[i-2]);
            if (i + 1 <= n - 2) best = Math.max(best, suf[i+1]);
            ans[i] = best;
        }
        return ans;
    }
}

