        auto lcp = [](const string& a, const string& b) {
            int m = min(a.size(), b.size()), i = 0;
            while (i < m && a[i] == b[i]) i++;
            return i;
        };
        vector<int> ans(n, 0);
        for (int rm = 0; rm < n; rm++) {
            int best = 0; const string* prev = nullptr;
            for (int i = 0; i < n; i++) {
                if (i == rm) continue;
                if (prev) best = max(best, lcp(*prev, words[i]));
                prev = &words[i];
            }
            ans[rm] = best;
        }
        return ans;
    }
};

