class Solution {
    public int[] longestCommonPrefix(String[] words) {
        int n = words.length;
        int[] ans = new int[n];
        for (int rm = 0; rm < n; rm++) {
            int best = 0; String prev = null;
            for (int i = 0; i < n; i++) {
                if (i == rm) continue;
                if (prev != null) {
                    int m = Math.min(prev.length(), words[i].length()), j = 0;
                    while (j < m && prev.charAt(j) == words[i].charAt(j)) j++;
                    best = Math.max(best, j);
                }
                prev = words[i];
            }
            ans[rm] = best;
        }
        return ans;
    }
}

